// CSD_RATIONALE_BEGIN
// Strategy for spider (text-to-SQL): emit free tokens until "<<" appears,
// then hard-constrain the SQL query inside the span, then close with ">>".
// Phase 1 (free prefix): up to prefixBudget unconstrained steps let the LM
// emit "SQL: <<" naturally; if "<<" is observed we enter the span without
// forcing an extra delimiter.
// Phase 2 (open span): if the LM did not emit "<<" itself, OpenConstrainedSpan
// forces it, consuming exactly 1 step.
// Phase 3 (constrained fill + close): CloseSpanWithinBudget generates
// parser-valid SQL tokens and emits ">>" within the remaining budget.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 – parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   Phase 1 (UnconstrainedStep loop): when "<<" is detected we set
//   currentConstrainedOut := [], and parser.IsValidPrefix([]) holds by
//   the method precondition; otherwise insideConstrainedOut stays false
//   and the invariant is vacuously true.
//   Phase 2 (OpenConstrainedSpan): postcondition guarantees insideOut=true
//   and currentOut=[], and parser.IsValidPrefix([]) holds by precondition.
//   Phase 3 (CloseSpanWithinBudget): postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut), so the invariant is
//   preserved on both the closed and still-open paths.
//
// Invariant 2 – progress:
//   |generated| <= |generatedPrefix| + steps
//   Phase 1: each loop iteration increments steps by 1 and appends at most
//   one token to generated (EOS breaks without appending), so
//   |generated| grows by at most 1 per step; the bound is maintained.
//   Phase 2: OpenConstrainedSpan appends exactly 1 token ("<<") and
//   steps is incremented by 1 simultaneously, preserving the bound.
//   Phase 3: CloseSpanWithinBudget postcondition states
//   |generatedOut| <= |generated| + remainingBudget, and we set
//   steps := steps + remainingBudget, so
//   |generatedOut| <= |generatedPrefix| + steps holds after the update.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  return;
}

var guidance: string := "Generate exactly: SQL: <<query>> with the SQL query inside << and >>. Rules: (1) Never add column aliases - do NOT write col AS alias_name. (2) For questions about 'how many', 'number of', 'count of distinct', use COUNT(*) or COUNT(DISTINCT col) - never bare SELECT DISTINCT when a count is asked. (3) Select only the specific column(s) the question asks about. Use only schema table and column names. Output nothing else.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var prefixBudget: nat := 6;
if prefixBudget > maxSteps {
  prefixBudget := maxSteps;
}

while steps < prefixBudget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases prefixBudget - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    insideConstrainedOut := true;
    currentConstrainedOut := [];
  }
}

if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

if insideConstrainedOut && steps < maxSteps {
  var remainingBudget: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainingBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + remainingBudget;
}

cost := steps;
